package local.boop.precision;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
public final class MenuActivityProbe extends Instrumentation {
 int checks;String result="";
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){try{
 for(String name:new String[]{"BoopProfileActivity","BoopAppearanceActivity","MainActivity"}){
 Intent intent=new Intent().setClassName("com.boop.shieldoverlay","com.boop.alpha1."+name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(name.equals("MainActivity"))intent.putExtra("boop_open_voice_settings",true);
 Activity a=startActivitySync(intent);waitForIdleSync();
 runOnMainSync(()->{List<View> views=new ArrayList<>();collect(a.getWindow().getDecorView(),views);int count=0;
 for(View v:views){if(v instanceof ScrollView){if(v.getOverScrollMode()!=View.OVER_SCROLL_NEVER)throw new AssertionError(name+" scroll glow");checks++;}
 if(v instanceof TextView&&v.isFocusable()&&v.isClickable()){v.requestFocus();try{Class<?> chrome=a.getClassLoader().loadClass("com.boop.shieldhome.BoopTvChrome");java.lang.reflect.Method decorate=chrome.getDeclaredMethod("decorateTree",View.class);decorate.setAccessible(true);decorate.invoke(null,a.getWindow().getDecorView());Object before=v.getBackground();for(int pass=0;pass<20;pass++)decorate.invoke(null,a.getWindow().getDecorView());if(v.getBackground()!=before)throw new AssertionError(name+" unchanged layout restyles focused control");checks++;}catch(ReflectiveOperationException e){throw new RuntimeException(e);}v.requestRectangleOnScreen(new android.graphics.Rect(0,0,v.getWidth(),v.getHeight()),true);android.util.Log.i("ScrollProbe","scale="+v.getScaleX());if(v.getScaleX()!=1f||v.getScaleY()!=1f)throw new AssertionError(name+" focus enlargement");if(v.getDefaultFocusHighlightEnabled())throw new AssertionError(name+" default blue");checks+=2;count++;}}
 if(count==0)throw new AssertionError(name+" no buttons");});waitForIdleSync();runOnMainSync(a::finish);
  }
 Activity launcher=startActivitySync(new Intent().setClassName("com.boop.shieldoverlay","com.boop.shieldhome.ShieldLauncherActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();SystemClock.sleep(500);waitForIdleSync();
 runOnMainSync(()->{try{java.lang.reflect.Field current=launcher.getClass().getDeclaredField("currentView");current.setAccessible(true);ViewGroup home=(ViewGroup)current.get(launcher);List<View> items=new ArrayList<>();collect(home,items);View settings=null;for(View v:items)if(v instanceof TextView&&"Home settings".contentEquals(((TextView)v).getText()))settings=v;if(settings==null)throw new AssertionError("Home settings exists");settings.requestFocus();settings.performClick();java.lang.reflect.Method back=launcher.getClass().getDeclaredMethod("handleShortBack");back.setAccessible(true);back.invoke(launcher);}catch(ReflectiveOperationException e){throw new RuntimeException(e);}});
 waitForIdleSync();SystemClock.sleep(200);waitForIdleSync();
 runOnMainSync(()->{View focused=launcher.getCurrentFocus();if(focused==null||!(focused instanceof TextView)||!"Home settings".contentEquals(((TextView)focused).getText()))throw new AssertionError("Back from Home settings restores Home settings, not favourite one: "+focused);checks++;});runOnMainSync(()->{try{Class<?> entry=launcher.getClassLoader().loadClass("com.boop.shieldhome.TvAppEntry");java.lang.reflect.Constructor<?> ctor=entry.getConstructor(String.class,String.class,String.class);java.lang.reflect.Field apps=launcher.getClass().getDeclaredField("installedApps"),favs=launcher.getClass().getDeclaredField("favouriteComponents");apps.setAccessible(true);favs.setAccessible(true);apps.set(launcher,List.of(ctor.newInstance("local.fixture.first/.Main","local.fixture.first","First app"),ctor.newInstance("local.youtube/.Main","local.youtube","YouTube")));favs.set(launcher,List.of("local.fixture.first/.Main","local.youtube/.Main"));java.lang.reflect.Method show=launcher.getClass().getDeclaredMethod("showHome");show.setAccessible(true);show.invoke(launcher);}catch(ReflectiveOperationException e){throw new RuntimeException(e);}});waitForIdleSync();
 runOnMainSync(()->{try{java.lang.reflect.Field current=launcher.getClass().getDeclaredField("currentView");current.setAccessible(true);Object home=current.get(launcher);java.lang.reflect.Method focus=home.getClass().getDeclaredMethod("restoreFocus",String.class);focus.setAccessible(true);if(!(Boolean)focus.invoke(home,"tag:local.youtube/.Main"))throw new AssertionError("YouTube fixture focus");}catch(ReflectiveOperationException e){throw new RuntimeException(e);}});
 Activity external=startActivitySync(new Intent().setClassName("com.boop.shieldoverlay","com.boop.alpha1.BoopProfileActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(external::finish);waitForIdleSync();SystemClock.sleep(200);waitForIdleSync();
 runOnMainSync(()->{View focus=launcher.getCurrentFocus();if(focus==null||!"local.youtube/.Main".equals(focus.getTag()))throw new AssertionError("Returning from program restores YouTube instead of first app: "+focus);checks++;callActivityOnNewIntent(launcher,new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME));});waitForIdleSync();SystemClock.sleep(200);waitForIdleSync();
 runOnMainSync(()->{View focus=launcher.getCurrentFocus();if(focus==null||!"local.fixture.first/.Main".equals(focus.getTag()))throw new AssertionError("HOME press resets first favourite: "+focus);checks++;});
 runOnMainSync(()->{try{java.lang.reflect.Method show=launcher.getClass().getDeclaredMethod("showSettings");show.setAccessible(true);show.invoke(launcher);}catch(ReflectiveOperationException e){throw new RuntimeException(e);}});waitForIdleSync();
 runOnMainSync(()->{List<View> rows=new ArrayList<>();collect(launcher.getWindow().getDecorView(),rows);for(View v:rows)if(v.isFocusable()&&matches(v,"Home Assistant controls")){v.requestFocus();v.requestRectangleOnScreen(new android.graphics.Rect(0,0,v.getWidth(),v.getHeight()),true);}});
for(int frame=0;frame<12;frame++){SystemClock.sleep(16);if(frame==5){android.graphics.Bitmap shot=getUiAutomation().takeScreenshot();java.io.File file=new java.io.File(getTargetContext().getExternalFilesDir(null),"settings-314.png");try(java.io.FileOutputStream output=new java.io.FileOutputStream(file)){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,output);}}runOnMainSync(()->{View v=launcher.getCurrentFocus();android.util.Log.i("ScrollProbe","scale="+v.getScaleX());if(v.getScaleX()!=1f||v.getScaleY()!=1f)throw new AssertionError("Launcher settings tile changes scale during focus/scroll: "+v.getScaleX());checks++;});}
for(String origin:new String[]{"BOOP device and room settings","Smart home panel:","Highlight Red","Highlight Green","Highlight Blue","Home Assistant controls","Android settings","Startup Manager","Media access:","Music audio access:","Player:","Play Next:","App content rows:"}){
 runOnMainSync(()->{List<View> items=new ArrayList<>();collect(launcher.getWindow().getDecorView(),items);View target=null;for(View v:items)if(v.isFocusable()&&matches(v,origin))target=v;if(target==null)throw new AssertionError("Settings origin exists: "+origin);target.requestFocus();target.requestRectangleOnScreen(new android.graphics.Rect(0,0,target.getWidth(),target.getHeight()),true);if(origin.equals("Play Next:")||origin.equals("App content rows:"))target.performClick();});
 Activity child=startActivitySync(new Intent().setClassName("com.boop.shieldoverlay","com.boop.alpha1.BoopProfileActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(child::finish);waitForIdleSync();SystemClock.sleep(200);waitForIdleSync();
 runOnMainSync(()->{View focus=launcher.getCurrentFocus();if(!matches(focus,origin))throw new AssertionError("Settings Back returns to originating entry "+origin+": "+focus);android.graphics.Rect visible=new android.graphics.Rect();if(!focus.getGlobalVisibleRect(visible)||visible.height()<focus.getHeight())throw new AssertionError("Settings origin fully visible after return: "+origin);checks+=2;});
 }
 Activity shortChild=startActivitySync(new Intent().setClassName("com.boop.shieldoverlay","com.boop.alpha1.BoopProfileActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
runOnMainSync(()->{android.view.Window.Callback callback=shortChild.getWindow().getCallback();callback.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_BACK));callback.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_BACK));});
SystemClock.sleep(200);waitForIdleSync();
runOnMainSync(()->{if(!shortChild.isFinishing())throw new AssertionError("Short Back keeps child Back behaviour");View focus=launcher.getCurrentFocus();if(!matches(focus,"App content rows:"))throw new AssertionError("Short Back keeps Settings origin");checks+=2;});
Activity holdChild=startActivitySync(new Intent().setClassName("com.boop.shieldoverlay","com.boop.alpha1.BoopProfileActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
runOnMainSync(()->holdChild.getWindow().getCallback().dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_BACK)));
SystemClock.sleep(500);waitForIdleSync();
runOnMainSync(()->{View focus=launcher.getCurrentFocus();if(focus==null||!"local.fixture.first/.Main".equals(focus.getTag()))throw new AssertionError("Held Back from child resets first favourite: "+focus);checks++;});
runOnMainSync(()->{try{java.lang.reflect.Method show=launcher.getClass().getDeclaredMethod("showSettings");show.setAccessible(true);show.invoke(launcher);launcher.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_BACK));}catch(ReflectiveOperationException e){throw new RuntimeException(e);}});
SystemClock.sleep(500);waitForIdleSync();
runOnMainSync(()->{View focus=launcher.getCurrentFocus();if(focus==null||!"local.fixture.first/.Main".equals(focus.getTag()))throw new AssertionError("Held Back from Launcher Settings resets first favourite: "+focus);checks++;launcher.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_BACK));});
runOnMainSync(()->{try{Class<?> type=launcher.getClassLoader().loadClass("com.boop.shieldhome.ShieldNowPlayingManager");Object manager=type.getMethod("get",Context.class).invoke(null,launcher);if(!(Boolean)type.getMethod("playDeezerFlow").invoke(manager))throw new AssertionError("Cold background Flow request accepted");}catch(ReflectiveOperationException e){throw new RuntimeException(e);}});
SystemClock.sleep(1500);waitForIdleSync();
runOnMainSync(()->{try{Class<?> type=launcher.getClassLoader().loadClass("com.boop.shieldhome.ShieldNowPlayingManager");Object manager=type.getMethod("get",Context.class).invoke(null,launcher);Object state=type.getMethod("state").invoke(manager);Object snapshot=state.getClass().getMethod("current").invoke(state);if(snapshot==null||!"Background Flow".equals(snapshot.getClass().getMethod("title").invoke(snapshot)))throw new AssertionError("Background Flow appears in Now Playing: "+snapshot);if(!launcher.hasWindowFocus())throw new AssertionError("Flow left launcher foreground");checks+=2;}catch(ReflectiveOperationException e){throw new RuntimeException(e);}});
runOnMainSync(launcher::finish);
 result="PASS "+checks+" legacy Settings, Appearance and Voice controls scrolled";
 }catch(Throwable e){result="FAIL "+e;}Bundle out=new Bundle();out.putString("result",result);finish(result.startsWith("PASS")?-1:0,out);}
 boolean matches(View v,String origin){return v!=null&&((v instanceof TextView&&((TextView)v).getText().toString().startsWith(origin))||(v.getContentDescription()!=null&&v.getContentDescription().toString().startsWith(origin)));}
 void collect(View v,List<View> out){out.add(v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)collect(g.getChildAt(i),out);}}
}